const app=document.querySelector('#app'),$=s=>document.querySelector(s);const initial={saved:[],requests:[],quiz:{},extras:[],messages:[],hostVerified:false};let state;try{state={...initial,...JSON.parse(localStorage.getItem('elsewhere-prototype-v2')||'{}')}}catch{state={...initial}}let selectedDate='',selectedDuration=0,guestCount=1,activeBookingId=0,extras=[],view='list',sortOrder='recommended',filters={q:'',interest:'',continent:'',duration:'',budget:'',month:'',comfort:'',language:'',cohort:''},quizStep=0;const save=()=>{localStorage.setItem('elsewhere-prototype-v2',JSON.stringify(state));$('#save-count').textContent=state.saved.length?`(${state.saved.length})`:''};save();const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');const fromPrice=e=>Math.round(e.price*e.days[0]/7);const euro=n=>'€'+Math.round(n).toLocaleString('en-GB');const duration=d=>d===2?'Weekend':d===7?'1 week':d===14?'2 weeks':d===21?'3 weeks':d===30?'1 month':d+' days';const find=id=>experiences.find(x=>x.id===Number(id));const to=h=>location.hash='#/'+h;function toast(t){let x=$('#toast');x.textContent=t;x.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>x.style.display='none',3000)}
function picture(e){return `<img src="${esc(e.image)}" alt="${esc(e.imageAlt)}">`};function card(e){return `<article class="card"><div class="photo"><a href="#/experience/${e.id}" aria-label="Explore ${esc(e.title)}">${picture(e)}<span class="badge">${esc(e.interest)}</span></a><button class="heart ${state.saved.includes(e.id)?'on':''}" data-save="${e.id}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}">${state.saved.includes(e.id)?'♥':'♡'}</button></div><div class="location">${esc(e.place)} · ${esc(e.continent)}</div><a href="#/experience/${e.id}"><h3>${esc(e.title)}</h3><p>${esc(e.desc)}</p></a><div class="card-meta"><span>${e.days.map(duration).join(' / ')}</span><span class="badge">Comfort ${e.comfort}/5</span></div><div class="card-meta"><span>with ${esc(e.host)}</span><strong>from ${euro(fromPrice(e))}</strong></div></article>`};function cards(es){return es.length?es.map(card).join(''):'<div class="empty">No experiences match those filters. Try changing your choices.</div>'};
function home(){return `<main><section class="hero"><img src="https://images.unsplash.com/photo-1472396961693-142e6e269027?auto=format&fit=crop&w=2200&q=85" alt="Sunlight in a green forest"><div class="hero-inner"><div class="eyebrow">A little time. A whole new perspective.</div><h1>Don’t visit.<br>Learn.</h1><p>Live and learn with the people who keep a tradition alive.</p><div class="button-row"><a href="#/discover" class="btn light">Explore experiences ↗</a><button class="btn" data-action="quiz">Find your kind of elsewhere</button></div></div></section><div class="wrap home-sections"><section class="section home-section home-feature"><div class="section-title"><div><div class="eyebrow">A few places to begin</div><h2>Learn from someone, somewhere.</h2><p class="sub">Small groups. Real practice. Time to be present.</p></div><a href="#/discover">See all experiences ↗</a></div><div class="discover-grid">${experiences.slice(0,3).map(discoverCard).join("")}</div></section><section class="section home-section"><div class="section-title"><div><div class="eyebrow">A different way to spend your time</div><h2>Stay curious. Go deeper.</h2><p class="sub">A weekend or a month can be enough to learn something with someone who knows it by heart.</p></div></div><div class="compare"><div><strong>Activity marketplaces</strong><p>Hours-long activities and a taste of a place.</p></div><div><strong>Work exchanges</strong><p>Work in exchange for a stay; learning varies.</p></div><div><strong>Retreats</strong><p>Often centred on one topic or institution.</p></div><div><strong>✳ Elsewhere Academy</strong><p>Days or weeks of guided learning rooted in a host’s everyday practice.</p></div></div></section><section class="section-sm home-section"><div class="eyebrow">Different lives, shared curiosity</div><h2>There’s more than one way to begin.</h2><div class="three"><div class="panel"><h3>Two weeks to breathe</h3><p class="sub">For a professional making space to learn and reset.</p></div><div class="panel"><h3>Try a different path</h3><p class="sub">For a career changer exploring a craft before taking the leap.</p></div><div class="panel"><h3>Stay a little longer</h3><p class="sub">For remote workers with a month, or students with a summer window.</p></div></div></section><section class="quiz home-section"><div><div class="eyebrow">Not sure where to begin?</div><h2>Find your kind of elsewhere.</h2><p class="sub">Three questions about your time, curiosity and comfort.</p></div><button class="btn" data-action="quiz">Take the 3-question quiz ↗</button></section><section class="section-sm"><div class="note">✳ &nbsp; Experiences on this prototype are fictional examples. Hosts, verification, availability, reviews and payment flows are simulated.</div></section></div></main>`}
const interestOptions=['Food','Craft','Music','Agriculture','Wellness','Language','Building','Nature & ecology'];const monthOptions=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function options(items,value,label){return `<option value="">${label}</option>`+items.map(x=>{let v=Array.isArray(x)?x[0]:x,t=Array.isArray(x)?x[1]:x;return `<option value="${esc(v)}" ${value==v?'selected':''}>${esc(t)}</option>`}).join('')}
function matches(f){let list=experiences.filter(e=>(!f.q||[e.title,e.place,e.desc,e.host,e.interest].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.interest||e.interest===f.interest)&&(!f.continent||e.continent===f.continent)&&(!f.duration||e.days.includes(Number(f.duration)))&&(!f.budget||e.price<=Number(f.budget))&&(!f.month||e.months.includes(f.month))&&(!f.comfort||e.comfort>=Number(f.comfort))&&(!f.language||e.language.toLowerCase().includes(f.language.toLowerCase()))&&(!f.cohort||(f.cohort==='solo'?e.solo:e.sharing)));if(sortOrder==='price-low')list.sort((a,b)=>a.price-b.price);if(sortOrder==='price-high')list.sort((a,b)=>b.price-a.price);if(sortOrder==='duration')list.sort((a,b)=>Math.min(...a.days)-Math.min(...b.days));return list}
function filterCount(f){return Object.keys(f).filter(k=>k!=='q'&&f[k]).length}function fmtRange(days){let a=Math.min(...days),b=Math.max(...days);if(a===b)return duration(a);if(a>=7&&a%7===0&&b%7===0)return `${a/7}–${b/7} weeks`;return `${duration(a)}–${duration(b)}`}
function discoverCard(e){let alt=esc(e.cardAlt||e.imageAlt||e.desc),dots=Array.from({length:5},(_,i)=>`<span class="comfort-dot ${i<e.comfort?'filled':''}"></span>`).join('');return `<article class="discover-card"><a class="discover-card-link" href="#/experience/${e.id}" aria-label="${esc(e.title)}, ${esc(e.place)}, ${esc(fmtRange(e.days))}, comfort ${e.comfort} out of 5, from ${euro(e.price)} per week"><div class="discover-image"><img src="${esc(e.cardImage||e.image)}" alt="${alt}" loading="lazy"><span class="category-chip">${esc(e.interest)}</span></div><div class="discover-card-body"><div class="discover-location">${esc(e.place)}</div><h3>${esc(e.title)}</h3><p class="discover-hook">${esc(e.cardHook||e.desc)}</p><div class="discover-bottom"><div class="discover-meta"><span>◷ &nbsp;${esc(fmtRange(e.days))}</span><span class="comfort" aria-label="Comfort ${e.comfort} out of 5">${dots}<span class="comfort-text">Comfort</span></span></div><div class="discover-footer"><span class="verified-badge">✓ &nbsp;Verified host</span><span class="discover-price">from ${euro(e.price)} <small>/ week</small></span></div></div></div></a><button class="heart ${state.saved.includes(e.id)?'on':''}" data-save="${e.id}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}" aria-pressed="${state.saved.includes(e.id)}">${state.saved.includes(e.id)?'♥':'♡'}</button></article>`}
function activeChips(){let labels={interest:'Interest',continent:'Destination',duration:'Duration',budget:'Budget',month:'Month',comfort:'Comfort',language:'Language',cohort:'Group'};return Object.entries(filters).filter(([k,v])=>k!=='q'&&v).map(([k,v])=>{let text=k==='duration'?duration(Number(v)):k==='budget'?'Up to '+euro(v)+'/week':k==='comfort'?v+'/5 or higher':k==='cohort'?(v==='solo'?'Private / solo':'Shared cohort'):v;return `<button class="applied-chip" data-remove-filter="${k}" aria-label="Remove ${labels[k]} filter">${esc(text)} <span>×</span></button>`}).join('')}
function discover(){let found=matches(filters);return `<main class="wrap discover-page"><div class="page-head discover-heading"><div class="eyebrow">The world is full of teachers</div><h1>Follow your curiosity.</h1><p class="sub">Find the people, places and practices that stay with you.</p></div><div class="demo-note"><span>✳</span> &nbsp; A concept to explore: experiences and verified host badges are illustrative.</div><div class="discover-toolbar"><form id="search-form" class="discover-search"><span aria-hidden="true">⌕</span><input name="search" value="${esc(filters.q)}" placeholder="Try matcha, weaving, Japan…" aria-label="Search experiences"><button type="submit" class="search-submit">Search</button></form><button class="filter-trigger" data-action="open-filters" aria-haspopup="dialog" aria-label="Filters, ${filterCount(filters)} applied">☷ &nbsp; Filters <span class="filter-count">${filterCount(filters)}</span></button><label class="sort-control">Sort: <select aria-label="Sort experiences" data-sort><option value="recommended" ${sortOrder==='recommended'?'selected':''}>Recommended</option><option value="price-low" ${sortOrder==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${sortOrder==='price-high'?'selected':''}>Price: high to low</option><option value="duration" ${sortOrder==='duration'?'selected':''}>Shortest first</option></select></label></div>${filterCount(filters)?`<div class="applied-filters" aria-label="Applied filters">${activeChips()}</div>`:''}<div class="discover-results"><div><strong>${found.length} ${found.length===1?'experience':'experiences'}</strong><span class="muted"> &nbsp;to get lost in</span></div><div class="view-toggle"><button class="${view==='list'?'selected':''}" data-view="list" aria-pressed="${view==='list'}">List</button><button class="${view==='map'?'selected':''}" data-view="map" aria-pressed="${view==='map'}">Map</button></div></div>${view==='list'?`<div class="discover-grid">${found.length?found.map(discoverCard).join(''):'<div class="empty">No experiences match those filters. Try changing your choices.</div>'}</div>`:`<div class="map"><h2>Explore by place</h2><p class="sub">Select a destination to open its experience. Locations are illustrative.</p><div class="world-map" role="img" aria-label="Illustrative world map"><svg viewBox="0 0 1000 420" preserveAspectRatio="none" aria-hidden="true"><path d="M45 74 L93 35 203 45 250 95 218 128 177 129 160 181 126 159 104 122 59 115Z M203 188 L238 194 267 222 278 274 244 355 221 339 210 290 190 249Z M425 75 L474 61 498 84 480 115 454 118Z M440 145 L497 129 551 155 567 206 534 287 492 305 466 249 442 205Z M508 76 L576 47 683 63 746 81 837 79 919 112 884 153 796 164 754 194 690 181 640 207 597 154 545 139 508 119Z M756 288 L812 270 869 290 887 327 842 354 784 342Z" fill="#c7d6bd"/></svg>${mapPins(found)}</div><div class="map-grid">${found.map(e=>`<button data-goto="experience/${e.id}">⌖ ${esc(e.place)} · ${esc(e.title)}</button>`).join('')||'No matching destinations.'}</div></div>`}<div class="section-sm"></div></main>`}
function openFilters(){let draft={...filters},d=document.createElement('dialog');d.className='filter-drawer';d.setAttribute('aria-label','Filter experiences');d.innerHTML=`<div class="drawer-shell"><div class="drawer-header"><div><span class="eyebrow">MAKE IT YOURS</span><h2>Find your fit.</h2></div><button class="drawer-close" aria-label="Close filters">×</button></div><div class="drawer-scroll"><section><h3>What would you like to learn?</h3><div class="drawer-chips">${interestOptions.map(x=>`<button class="drawer-chip" data-pick="interest" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div></section><section><h3>Destination</h3><select aria-label="Destination" data-draft="continent">${options(['Africa','Asia','Europe','North America','South America','Oceania'],draft.continent,'Anywhere in the world')}</select></section><section><h3>Time to immerse</h3><div class="drawer-chips">${[[2,'Weekend'],[7,'1 week'],[14,'2 weeks'],[30,'Up to 1 month']].map(([v,l])=>`<button class="drawer-chip" data-pick="duration" data-value="${v}">${l}</button>`).join('')}</div></section><section><div class="drawer-section-title"><h3>Budget per week</h3><strong id="budget-value">Any budget</strong></div><input type="range" aria-label="Maximum budget per week" id="budget-slider" min="0" max="5000" step="50" value="${draft.budget||5000}"><div class="slider-labels"><span>€0</span><span>€5,000+</span></div><button class="text-button" data-draft-clear="budget">Any budget</button></section><section><h3>Month</h3><select aria-label="Month" data-draft="month">${options(monthOptions,draft.month,'Any month')}</select></section><section><h3>Minimum comfort</h3><div class="drawer-chips">${[1,2,3,4,5].map(x=>`<button class="drawer-chip" data-pick="comfort" data-value="${x}">${x} / 5</button>`).join('')}</div></section><section><h3>Language of instruction</h3><select aria-label="Language of instruction" data-draft="language">${options(['English','French','Spanish','Japanese','Portuguese','Italian','Arabic','Indonesian'],draft.language,'Any language')}</select></section><section><h3>Solo or group</h3><div class="drawer-chips"><button class="drawer-chip" data-pick="cohort" data-value="solo">Private / solo</button><button class="drawer-chip" data-pick="cohort" data-value="group">Shared cohort</button></div></section></div><div class="drawer-footer"><button class="text-button" data-draft-clear="all">Clear all</button><button class="btn" data-apply>Show experiences</button></div></div>`;document.body.append(d);function update(){d.querySelectorAll('[data-pick]').forEach(b=>{let on=String(draft[b.dataset.pick])===b.dataset.value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});d.querySelectorAll('[data-draft]').forEach(el=>el.value=draft[el.dataset.draft]||'');d.querySelector('#budget-slider').value=draft.budget||5000;d.querySelector('#budget-value').textContent=draft.budget?`Up to ${euro(draft.budget)}`:'Any budget';let n=matches(draft).length;d.querySelector('[data-apply]').textContent=`Show ${n} ${n===1?'experience':'experiences'}`}
 d.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b){if(ev.target===d)d.close();return}if(b.classList.contains('drawer-close'))d.close();if(b.dataset.pick){let k=b.dataset.pick;draft[k]=String(draft[k])===b.dataset.value?'':b.dataset.value;update()}if(b.dataset.draftClear==='budget'){draft.budget='';update()}if(b.dataset.draftClear==='all'){draft={q:filters.q,interest:'',continent:'',duration:'',budget:'',month:'',comfort:'',language:'',cohort:''};update()}if(b.hasAttribute('data-apply')){filters=draft;d.close();preserve()}});d.addEventListener('input',ev=>{if(ev.target.id==='budget-slider'){draft.budget=Number(ev.target.value)>=5000?'':ev.target.value;d.querySelector('#budget-value').textContent=draft.budget?`Up to ${euro(draft.budget)}`:'Any budget';let n=matches(draft).length;d.querySelector('[data-apply]').textContent=`Show ${n} ${n===1?'experience':'experiences'}`}});d.addEventListener('change',ev=>{if(ev.target.dataset.draft){draft[ev.target.dataset.draft]=ev.target.value;update()}});d.addEventListener('close',()=>{d.remove();document.querySelector('[data-action="open-filters"]')?.focus()});update();d.showModal()}
function mapPins(found){const coords={Africa:[48,46],Asia:[70,26],Europe:[48,20],'North America':[17,23],'South America':[24,58],Oceania:[83,72]};return found.map(e=>{let p=coords[e.continent],n=found.filter(x=>x.continent===e.continent).findIndex(x=>x.id===e.id);return `<button class="map-pin" style="left:${p[0]+n%4*2}%;top:${p[1]+Math.floor(n/4)*5}%" data-goto="experience/${e.id}" title="${esc(e.title)} · ${esc(e.place)}" aria-label="${esc(e.title)} in ${esc(e.place)}">⌖</button>`}).join('')}
function galleryFor(e){if(e.id===20)return [{src:'assets/marrakech/oven.jpg',alt:'A cook preparing bread beside an oven'},{src:'assets/marrakech/dough.jpg',alt:'Hands shaping bread dough'},{src:'assets/marrakech/kitchen.jpg',alt:'A cook preparing food in a Moroccan kitchen'},{src:'assets/detail/meal.jpg',alt:'People sharing a meal around a table'},{src:'assets/marrakech/stay.jpg',alt:'Traditional tiled interior in Marrakech'}];if(e.id===7)return [{src:'assets/detail/landscape.jpg',alt:'Green farmland and coastline in Tasmania'},{src:'assets/detail/craft.jpg',alt:'A beekeeper inspecting a honeycomb'},{src:'assets/detail/together.jpg',alt:'Two beekeepers working together'},{src:'assets/detail/meal.jpg',alt:'People sharing a meal around a table'},{src:'assets/detail/stay.jpg',alt:'A warm cabin bedroom'}];let subject=e.cardImage||e.image,other=e.image!==subject?e.image:(experiences.find(x=>x.interest===e.interest&&x.id!==e.id&&(x.cardImage||x.image)!==subject)?.cardImage||'assets/detail/craft.jpg'),third=experiences.find(x=>x.interest===e.interest&&x.id!==e.id&&(x.cardImage||x.image)!==subject&&(x.cardImage||x.image)!==other);return [{src:subject,alt:e.cardAlt||e.imageAlt},{src:other,alt:'A closer view of the practice'},{src:third?.cardImage||'assets/detail/together.jpg',alt:'People sharing skills'},{src:'assets/detail/meal.jpg',alt:'People sharing a meal around a table'},{src:'assets/detail/stay.jpg',alt:'A welcoming guest room'}]}
function skillsFor(e){let sets={Agriculture:[['♧','Read the rhythms','Notice the seasonal patterns that shape daily work.'],['⌁','Work with care','Practise the tools and routines alongside your host.'],['☼','Understand the environment','Explore how weather and local conditions shape the practice.'],['✦','Build confidence','Learn safe techniques you can continue to develop.']],Food:[['♧','Start with ingredients','Discover local ingredients and how they are prepared.'],['⌁','Practise by hand','Learn foundational techniques alongside your host.'],['☼','Understand the process','Explore the timing and decisions behind each stage.'],['✦','Taste and reflect','Develop your palate and keep notes on what you learn.']],Craft:[['⌁','Meet the materials','Learn how the materials are selected and prepared.'],['✂','Learn the tools','Get comfortable with the tools and basic techniques.'],['✦','Practise each step','Build skills through patient, hands-on guidance.'],['◌','Make something your own','Work towards a small piece while respecting local traditions.']],Music:[['♪','Find the rhythm','Practise the fundamental patterns and phrasing.'],['⌁','Get to know the instrument','Explore its construction, sound and care.'],['♬','Practise together','Learn through listening and guided repetition.'],['✦','Understand the context','Hear how the music is shared in daily life.']],Language:[['◌','Start a conversation','Practise greetings and useful everyday phrases.'],['♬','Listen closely','Build confidence with pronunciation and rhythm.'],['⌁','Learn in context','Use language around meals and daily routines.'],['✦','Take notes home','Build a personal phrasebook for continued practice.']],Building:[['⌁','Meet the materials','Explore how earth is prepared for building.'],['◫','Learn foundational techniques','Practise mixing and compacting under guidance.'],['♧','Work safely together','Learn to use tools and protect yourself on site.'],['✦','Understand the craft','Discover why local climate and materials matter.']],Wellness:[['♧','Get to know local plants','Notice their textures, scents and growing conditions.'],['☼','Slow down and observe','Practise a mindful approach to everyday routines.'],['⌁','Try simple preparations','Learn safe, guided techniques with your host.'],['✦','Build a personal practice','Keep notes on what you would like to continue.']]};if(e.id===2)return [['⌁','Choose and shape the wood','Learn how the shell is prepared and shaped.'],['✂','Fit the drumhead','Explore how hide and rope are assembled.'],['✦','Tune the drum','Practise tensioning and listening for the sound.'],['♪','Hear it come alive','Try foundational rhythms on a finished instrument.']];if(e.id===7)return [['♧','Understand the hive','Observe how a colony works and changes through the seasons.'],['⌁','Inspect a hive safely','Use protective gear and learn a calm approach to the bees.'],['✦','Read the frames','Recognise brood, honey stores and signs of colony health.'],['☼','Follow the honey','Explore how honey is handled, extracted and stored.'],['❋','Support pollinators','Learn how nearby plants and habitat sustain bees.']];return sets[e.interest]||sets.Agriculture}
const hostStories=[
"In the tea garden, I look for the youngest leaves and the right moment to pick them. I invite guests to follow that leaf through the mill and into a bowl, with time to notice how each step changes its character.",
"I work with wood, hide and rope to make drums that can hold both a voice and a rhythm. In the workshop, I show guests how the parts come together and why careful tuning matters as much as shaping the shell.",
"My studio days start by preparing clay and seeing how it responds to my hands. I like to teach the wheel slowly, making space for uneven pots and the small discoveries that come with practice.",
"I work alongside other producers to turn shea nuts into butter. The process takes patience and many hands; I enjoy sharing each step, from sorting the nuts to watching the butter come together.",
"I learned to pay attention to fibre, colour and tension at the loom. I welcome guests to practise the steps with me, and to understand the care and time behind a woven piece.",
"Coffee growing has taught me to look closely at soil, weather and the ripeness of a cherry. I share the farm’s daily routines and the decisions that shape the taste of a cup.",
"","At the furnace, timing changes everything. I teach beginners how we gather and shape glass, and why listening to the material is as important as learning to use a tool.",
"I spend the year caring for olive trees and waiting for the harvest. Around the table, I help guests taste the differences between oils and connect those flavours to the grove.",
"I love the moment a stack of loose pages becomes a book. In my workshop, I teach folding, stitching and finishing, with enough time to appreciate the character of the paper.",
"I work with broken ceramics and the patient stages of lacquer repair. I invite guests to look closely at a piece before beginning, and to respect the time each layer needs to cure.",
"My work revolves around the indigo vat and the fabric that passes through it. I show guests how a colour is built through repeated dips and the transformation that happens in the air.",
"I follow cacao from the trees through fermentation, drying and roasting. I like sharing how the choices made on a small farm become the flavours people recognise in chocolate.",
"The bakery starts early, with dough, butter and a careful eye on temperature. I teach guests the folds and timing of laminated pastry, one patient batch at a time.",
"Mushroom growing asks you to notice humidity, cleanliness and tiny changes every day. I share the work of preparing a substrate and looking after a crop as it grows.",
"I work with willow that can be soaked, bent and woven into something useful. My favourite part of teaching is watching a basket take shape from a handful of flexible stems.",
"I use wax to draw lines that will resist the dye. I teach guests how to handle the canting and build a pattern carefully, while sharing the designs I choose to make open to learners.",
"In the dairy, small choices of temperature and timing shape the curd. I guide guests through the work I do each morning and explain how patience continues the process after the cheese is made.",
"I teach Twi through the conversations that make up a day: greetings, meals and the questions we ask one another. I want guests to leave with words they can actually use and the confidence to keep listening.",
"I love the warmth and conversation of a kitchen where bread is made by hand. Guests join me to mix, shape and cook, then we sit down and share what we have prepared.",
"Earth is my building material and the local climate is part of every design decision. I teach guests to prepare and compact a small practice section, safely and at a pace that leaves room for questions.",
"I prepare plant fibres before they are ready to weave, and I enjoy showing how much thought goes into that first step. Guests practise the fundamentals with me and learn which materials I choose to share.",
"The dishes I cook change with the ingredients available around us. I invite guests into the kitchen to prepare an everyday meal together and learn the stories I share around the table.",
"I begin in the garden by checking the soil and what the season is asking of us. Guests learn by helping with planting and composting, then taking the time to observe what is growing.",
"I enjoy the patient work of preparing fibre and setting up a loom. In our sessions, guests practise the basics and see how the choices of material and colour shape a textile.",
"I learned pandeiro by listening and playing with others. I teach the first patterns slowly, then we bring them together so guests can feel the conversation inside the rhythm.",
"I like to start a walk by looking closely at the plants underfoot. I teach observation and responsible identification, with a focus on learning what belongs in a place rather than collecting indiscriminately.",
"Fermentation is part of the rhythm of my kitchen. I show guests how we prepare seasonal vegetables and build flavour, and explain what changes while they rest.",
"My garden is where I pay attention to scent, texture and the changing light. I share gentle ways to observe aromatic plants and make simple preparations with care.",
"I bring songs and everyday conversation into my language lessons. Guests can practise without worrying about perfect grammar, and leave with phrases they have used in real exchanges."
];
function hostCopy(e){if(e.id===7)return {years:12,story:'I started keeping bees in a borrowed corner of my neighbour’s orchard. What began with one hive became a way to understand the landscape around me. Today I care for a small apiary and teach visitors how to move slowly, notice the details and give the bees the space they need.',quote:'The best thing I can teach you is to stop, watch and let the bees tell you what is happening.'};let by={Craft:`I spend my days working with materials, tools and the small details that make each piece different. I love inviting curious beginners into the workshop, sharing the techniques I use and making room for them to find their own pace.`,Food:`My days begin with ingredients and the people who grow them. I enjoy sharing the everyday techniques behind the food I make, and the conversations that happen while we prepare and eat together.`,Agriculture:`My work changes with the weather and the seasons. I welcome guests into those daily rhythms and teach the practical skills that help us care for the land and the living things around us.`,Music:`I learned by listening, practising and making music with other people. Now I share the rhythms and stories that shape my practice, one beat and one conversation at a time.`,Language:`I believe language opens the door to everyday life. We learn through conversation, shared moments and the small phrases that help us feel at home with one another.`,Building:`I work with earth because it connects a building to the place around it. I teach the materials and methods step by step, with time to practise safely and understand the local context.`,Wellness:`My work begins in the garden, paying attention to plants and the changing seasons. I enjoy sharing simple ways to slow down, observe and care for the world around us.`};return {years:6+(e.id%9),story:hostStories[e.id-1]||by[e.interest]||by.Agriculture,quote:'Come with curiosity. We will take the time to learn together.'}}
function dots(n){return `<span class="detail-dots" aria-label="${n} out of 5">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'filled':''}"></i>`).join('')}</span>`}function endDate(date,days){if(!date)return 'Choose a start date';let x=new Date(date+'T12:00:00');x.setDate(x.getDate()+days-1);return x.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}function bookingTotal(e){return Math.round(e.price*(selectedDuration||e.days[0])/7)*guestCount}
const approximateAreas=[[34.89,135.80],[5.36,-4.00],[38.57,-7.91],[10.30,1.38],[17.07,-96.72],[4.64,-75.57],[-41.52,146.65],[45.46,12.35],[37.04,22.11],[43.77,11.25],[35.01,135.77],[34.07,134.55],[-0.99,-77.81],[45.76,4.84],[49.65,-125.30],[51.10,-3.00],[-7.80,110.36],[46.58,7.08],[5.60,-0.19],[31.63,-7.98],[31.63,-7.98],[-38.13,176.25],[-17.80,177.42],[-28.65,153.40],[-13.53,-71.97],[-12.97,-38.50],[53.0,-125.0],[37.56,126.98],[43.90,5.40],[41.39,2.17]];function areaMap(e){let [lat,lon]=approximateAreas[e.id-1],wide=[3,15,16,27,29].includes(e.id)?1.5:.3,bbox=[lon-wide,lat-wide*.6,lon+wide,lat+wide*.6].join('%2C');return `<iframe class="location-map" title="Approximate area near ${esc(e.place)}" loading="lazy" src="https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&amp;layer=mapnik"></iframe>`}
function detail(e){if(activeBookingId!==e.id){activeBookingId=e.id;selectedDate='';selectedDuration=e.days[0];guestCount=1;extras=[]}let g=galleryFor(e),host=hostCopy(e),sim=experiences.filter(x=>x.id!==e.id&&(x.interest===e.interest||x.continent===e.continent)).slice(0,3),skill=skillsFor(e),saved=state.saved.includes(e.id),m=e.id===7;let placeLink='https://www.openstreetmap.org/search?query='+encodeURIComponent(e.place);return `<main class="detail-page wrap"><div class="detail-topline"><a class="back" href="#/discover">← Back to discovery</a><div class="detail-actions"><button data-share="${e.id}">↗ &nbsp; Share</button><button data-save="${e.id}">${saved?'♥ &nbsp; Saved':'♡ &nbsp; Save'}</button></div></div><div class="detail-title"><h1>${esc(e.title)}</h1><div class="detail-subline"><span>${m?'★ 4.9 (12 reviews)':'<span class="new-badge">New</span>'}</span><span>⌖ &nbsp;${esc(e.place)}</span><span class="verified-badge">✓ &nbsp;Verified host</span></div></div><div class="gallery-grid" id="experience-gallery">${g.map((im,i)=>`<button class="gallery-tile gallery-tile-${i}" data-open-photo="${e.id}" data-photo-index="${i}" aria-label="View photo ${i+1} of 5: ${esc(im.alt)}"><img src="${esc(im.src)}" alt="${esc(im.alt)}" loading="${i?'lazy':'eager'}">${i===4?'<span class="show-photos">▦ &nbsp; Show all photos</span>':''}</button>`).join('')}</div><div class="gallery-mobile" id="gallery-mobile">${g.map((im,i)=>`<button class="gallery-slide" data-open-photo="${e.id}" data-photo-index="${i}" aria-label="View photo ${i+1} of 5: ${esc(im.alt)}"><img src="${esc(im.src)}" alt="${esc(im.alt)}"></button>`).join('')}</div><div class="gallery-counter" id="gallery-counter">1 / 5</div><div class="facts-strip"><div><span>◷</span><p><small>Duration</small><strong>${esc(fmtRange(e.days))}</strong></p></div><div><span>♧</span><p><small>Group size</small><strong>${esc(e.group)}</strong></p></div><div><span>◌</span><p><small>Language</small><strong>${esc(e.language)}</strong></p></div><div><span>⌂</span><p><small>Comfort</small><strong>${dots(e.comfort)}</strong></p></div><div><span>☼</span><p><small>Best season</small><strong>${esc(e.season)}</strong></p></div></div><div class="detail-nav"><button data-scroll="overview">Overview</button><button data-scroll="host">Host</button><button data-scroll="day">Day</button><button data-scroll="stay">Stay</button><button data-scroll="reviews">Reviews</button></div><div class="experience-columns"><div class="experience-content"><section class="experience-section" id="overview"><h2>What you’ll learn</h2><p>${esc(e.desc)}</p><div class="skill-list">${skill.map(([icon,title,desc])=>`<div class="skill"><span>${icon}</span><div><strong>${esc(title)}</strong><p>${esc(desc)}</p></div></div>`).join('')}</div><div class="outcome"><span>✧</span><div><strong>Your outcome</strong><p>${esc(e.outcome)}.</p></div></div></section><section class="experience-section" id="host"><h2>Meet your host</h2><div class="detail-host"><img src="${esc(e.portrait)}" alt="Representative photograph for ${esc(e.host)}"><div><div class="host-heading"><h3>${esc(e.host)}</h3><span class="verified-badge">✓ &nbsp;Verified host</span></div><p class="host-meta">${host.years} years of experience &nbsp; · &nbsp; ${esc(e.language)}</p><p>${esc(host.story)}</p><blockquote>“${esc(host.quote)}”</blockquote><button class="text-link" data-ask-host="${e.id}">Message host</button></div></div></section><section class="experience-section included-section"><h2>What’s included</h2><ul><li>Guided learning with your host and shared materials</li><li>Accommodation for the experience duration</li><li>Breakfast and one shared meal each day</li><li>Instruction in ${esc(e.language)}</li></ul><p>Flights, visa fees, travel insurance and meals not listed are not included. A dedicated translator is not included.</p></section><section class="experience-section" id="day"><h2>Itinerary</h2><p class="section-intro">A gentle rhythm, with room for questions and time to take it all in.</p><div class="day-layout"><div class="day-timeline">${[['☼','08:30','Start together','Breakfast and a conversation about the day ahead.'],['⌁','09:30',m?'Meet the bees':'Time to practise',m?'Suit up and inspect the hives with your host.':'Join your host for guided hands-on learning.'],['♧','12:30','Share a meal','Pause for lunch and a little time to rest.'],['✦','14:00','Continue learning',m?'Explore honey handling, the frames and colony care.':'Keep practising, ask questions and compare notes.'],['◌','17:00','Make the evening yours','Rest, explore nearby or join an optional meal.']].map(([icon,time,title,desc])=>`<div class="day-step"><span class="timeline-icon">${icon}</span><div><small>${time}</small><strong>${esc(title)}</strong><p>${esc(desc)}</p></div></div>`).join('')}</div><img src="${esc(g[2].src)}" alt="${esc(g[2].alt)}"></div></section><section class="experience-section" id="stay"><h2>Where you’ll stay</h2><p>Settle into a locally run guesthouse, with time for shared meals and quiet moments of your own.</p><img class="stay-image" src="${esc(g[4].src)}" alt="${esc(g[4].alt)}"><div class="stay-rating">${[['Accommodation',e.comfort,'A private room with simple, comfortable furnishings.'],['Food',Math.min(5,e.comfort+1),'Breakfast and one shared meal each day.'],['Bathroom',e.comfort,e.comfort>=4?'A private bathroom with hot water.':'A shared bathroom; hot water may vary.'],['Connectivity',Math.max(1,e.comfort-1),e.comfort>=4?'Wi-Fi is available; speeds can vary.':'Wi-Fi may be limited or intermittent.'],['Physical effort',e.interest==='Building'?4:2,e.effort+'.']].map(([name,n,desc])=>`<div class="rating-row"><div><strong>${name}</strong><p>${esc(desc)}</p></div>${dots(n)}</div>`).join('')}</div><p class="rating-note">For physical effort, more dots mean a more demanding activity.</p></section><section class="experience-section" id="good-to-know"><h2>Good to know</h2><div class="good-grid"><div><span>♧</span><h3>Cultural etiquette</h3><p>Ask before taking photos and follow your host’s guidance. Family spaces and ceremonies may be private.</p></div><div><span>✚</span><h3>Safety & emergency</h3><p>Your host explains site safety. ${m?'For an emergency in Australia, call 000 for police, fire or ambulance.':'For urgent help, contact local emergency services.'} A host contact is shared before departure.</p>${m?'<a class="text-link" href="https://www.triplezero.gov.au/" target="_blank" rel="noopener">Australian emergency guidance ↗</a>':'<button class="text-link" data-action="emergency">Emergency information</button>'}</div><div><span>♿</span><h3>Accessibility</h3><p>Ask your host about step-free access and adaptations before booking.</p></div><div><span>⌁</span><h3>What to bring</h3><p>${m?'Closed shoes, long sleeves and comfortable outdoor clothing. Protective equipment is provided.':'Comfortable clothes suitable for the work, closed shoes and a reusable water bottle.'}</p></div></div></section><section class="experience-section"><h2>Community impact</h2><p>Your time and your payment can support the people sharing their knowledge.</p><div class="impact-line"><strong>${e.hostShare}%</strong><div><b>Goes to your host</b><p>For teaching, hosting and the work behind your stay.</p></div></div><div class="impact-line"><strong>${e.communityShare}%</strong><div><b>Supports the community</b><p>A contribution to a fund selected by your host.</p></div></div><p class="rating-note">The remaining 25% covers platform and guest support.</p></section><section class="experience-section" id="reviews"><h2>${m?'★ 4.9 · 12 reviews':'Reviews'}</h2>${m?`<div class="review-grid"><div><b>★★★★★</b><h3>“A week that stayed with me.”</h3><p>Mia made space for every question. I left with a much better understanding of bees and the care behind the honey.</p><small>Alex · March 2026</small></div><div><b>★★★★★</b><h3>“Learning at a different pace.”</h3><p>The days felt grounded and generous. I loved being able to practise, then sit down and share a meal together.</p><small>Sam · January 2026</small></div></div>`:'<p>No reviews yet. Be the first to share your experience after your stay.</p>'}</section><section class="experience-section"><h2>Cancellation policy</h2><p>Cancel at least 30 days before the start for a full refund; 15–29 days before for 50%. Within 14 days, the booking is non-refundable.</p><p>If your host cancels, you receive a full refund, including fees. Travel insurance is recommended.</p></section><section class="experience-section"><h2>Where you’ll be</h2><p>⌖ &nbsp;${esc(e.place)}</p>${areaMap(e)}<p><a class="text-link" target="_blank" rel="noopener" href="${placeLink}">Explore the area on OpenStreetMap ↗</a></p><p class="rating-note">The exact meeting location is shared after acceptance.</p></section></div><aside class="detail-booking" id="booking-card"><button class="booking-close" data-close-booking aria-label="Close booking details">×</button><div class="booking-head">From <strong id="detail-price">${euro(Math.round(e.price*selectedDuration/7))}</strong> <span>per person</span></div><div class="booking-fields"><div class="booking-field date-field"><label>Dates</label><button id="date-trigger" type="button" aria-haspopup="dialog" aria-expanded="false">${selectedDate?esc(new Date(selectedDate+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}))+' – '+esc(endDate(selectedDate,selectedDuration)):'Add date'}</button><div id="calendar-popover" class="calendar-popover" hidden></div></div><div class="booking-field"><label for="detail-duration">Duration</label><select id="detail-duration">${e.days.map(d=>`<option value="${d}" ${selectedDuration===d?'selected':''}>${duration(d)}</option>`).join('')}</select></div><div class="booking-field"><label for="detail-guests">Guests</label><select id="detail-guests">${[1,2,3,4].map(n=>`<option value="${n}" ${guestCount===n?'selected':''}>${n} ${n===1?'guest':'guests'}</option>`).join('')}</select></div></div><div class="booking-breakdown" ${selectedDate?'':'hidden'}><div><span id="detail-rate">${euro(Math.round(e.price*selectedDuration/7))} × ${guestCount} ${guestCount===1?'guest':'guests'}</span><span id="detail-subtotal">${euro(bookingTotal(e))}</span></div><div><span>Taxes and fees</span><span>Included</span></div><div class="booking-total"><strong>Total</strong><strong id="detail-total">${euro(bookingTotal(e))}</strong></div></div><button class="btn detail-cta" data-detail-book="${e.id}">Request to join</button><p class="booking-trust">You won’t be charged yet<br>Host replies within 72 hours</p><p class="cancellation-note">Free cancellation until 30 days before</p></aside></div><section class="similar-section"><div class="section-title"><div><span class="eyebrow">KEEP FOLLOWING YOUR CURIOSITY</span><h2>Similar experiences</h2></div><a href="#/discover">See all experiences ↗</a></div><div class="discover-grid">${sim.map(discoverCard).join('')}</div></section><div class="mobile-booking-bar"><div><strong id="mobile-price">From ${euro(Math.round(e.price*selectedDuration/7))}</strong><small>per person · ${duration(selectedDuration)}</small></div><button class="btn" data-detail-book="${e.id}">Request to join</button></div></main>`}
function detailGallery(e,index=0){let g=galleryFor(e),d=document.createElement('dialog');d.className='photo-dialog';d.setAttribute('aria-label','Photo gallery');d.innerHTML=`<div class="photo-viewer"><div class="photo-viewer-head"><b>Photos · ${esc(e.title)}</b><button class="drawer-close" data-photo-close aria-label="Close gallery">×</button></div><img id="photo-viewer-img" src="${esc(g[index].src)}" alt="${esc(g[index].alt)}"><div class="photo-viewer-footer"><button class="btn outline small" data-photo-prev aria-label="Previous photo">←</button><span id="photo-viewer-count">${index+1} / 5</span><button class="btn outline small" data-photo-next aria-label="Next photo">→</button></div></div>`;document.body.append(d);d.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b){if(ev.target===d)d.close();return}if(b.hasAttribute('data-photo-close'))d.close();if(b.hasAttribute('data-photo-prev'))index=(index+4)%5;if(b.hasAttribute('data-photo-next'))index=(index+1)%5;let img=d.querySelector('#photo-viewer-img');img.src=g[index].src;img.alt=g[index].alt;d.querySelector('#photo-viewer-count').textContent=`${index+1} / 5`});d.addEventListener('close',()=>d.remove());d.showModal()}
function dates(e){if(!selectedDuration||!e.days.includes(selectedDuration))selectedDuration=e.days[0];let base=Math.round(e.price*selectedDuration/7)*guestCount,total=base+extras.reduce((s,x)=>s+Number(x),0)*guestCount;return `<main class="narrow"><div class="page-head"><a class="back" href="#/experience/${e.id}">← Back to experience</a><div class="steps"><b>01 &nbsp; Dates & inclusions</b> → 02 &nbsp; Your introduction → 03 &nbsp; Request sent</div><h1>Make time for this.</h1><p class="sub">Choose a sample start date and see what is included.</p></div><div class="form-layout"><div><div class="form-card"><h2>Choose your dates</h2><p class="sub">Illustrative availability only. Choose any future date to explore the flow.</p><div class="form-group"><label for="start">Start date</label><input id="start" type="date" value="${esc(selectedDate)}" min="2026-10-30"></div><div class="form-group"><label for="duration">Length</label><select id="duration">${e.days.map(d=>`<option value="${d}" ${selectedDuration===d?'selected':''}>${duration(d)} · ${d} days</option>`).join('')}</select></div><div class="form-group"><label for="guest-count">Guests</label><select id="guest-count">${[1,2,3,4].map(n=>`<option value="${n}" ${guestCount===n?'selected':''}>${n} ${n===1?'guest':'guests'}</option>`).join('')}</select></div></div><div class="form-card"><h2>What’s included</h2><ul class="list"><li>Guided learning with your host and shared materials</li><li>Accommodation for the experience duration</li><li>Breakfast and one shared meal each day</li><li>Instruction in ${esc(e.language)}</li></ul><h3>Not included</h3><p>Flights, visa fees, travel insurance and meals not listed. A dedicated translator is not included.</p></div><div class="form-card"><h2>Make it yours</h2><p class="sub">Optional extras, per guest.</p><label class="extra-option"><span class="extra-name"><input type="checkbox" data-extra="60" ${extras.includes('60')?'checked':''}><span>Airport pickup</span></span><span class="extra-price">+€60<small> per guest</small></span></label><label class="extra-option"><span class="extra-name"><input type="checkbox" data-extra="90" ${extras.includes('90')?'checked':''}><span>Extra night</span></span><span class="extra-price">+€90<small> per guest</small></span></label><label class="extra-option"><span class="extra-name"><input type="checkbox" data-extra="45" ${extras.includes('45')?'checked':''}><span>Personal gear</span></span><span class="extra-price">+€45<small> per guest</small></span></label></div><div class="form-card"><h2>Cancellation & peace of mind</h2><p>Sample policy: cancel at least 30 days before the start for a full refund; 15–29 days for 50%; within 14 days, no refund. If the host cancels, you receive a full refund, including service fees.</p><p>We recommend travel insurance that covers cancellation, medical care and the activities you plan to do. Terms and coverage vary.</p><p class="demo-tag">Illustrative terms for this prototype</p></div></div><aside class="panel booking"><h3>${esc(e.title)}</h3><p class="muted">${esc(e.place)} · ${esc(e.host)}</p><div class="price-line"><span>Experience · ${duration(selectedDuration)} · ${guestCount} ${guestCount===1?'guest':'guests'}</span><span>${euro(base)}</span></div>${extras.map(x=>`<div class="price-line"><span>${x==='60'?'Airport pickup':x==='90'?'Extra night':'Personal gear'}</span><span>${euro(Number(x)*guestCount)}</span></div>`).join('')}<div class="price-line total"><span>Total · taxes & fees included</span><span>${euro(total)}</span></div><p class="muted" style="font-size:11px">Includes the sample host, community and platform shares; no hidden service fee.</p><button class="btn" data-next-request="${e.id}">Continue to introduction ↗</button><p class="muted" style="font-size:11px">No charge in this prototype.</p></aside></div></main>`}
function request(e){return `<main class="narrow"><div class="page-head"><a class="back" href="#/dates/${e.id}">← Back to dates</a><div class="steps">01 &nbsp; Dates & inclusions → <b>02 &nbsp; Your introduction</b> → 03 &nbsp; Request sent</div><h1>Say hello to ${esc(e.host.split(' ')[0])}.</h1><p class="sub">A little about you helps your host make sure the experience is a good fit.</p></div><div class="form-layout"><form id="request-form" data-id="${e.id}" class="form-card"><div class="form-group"><label for="name">Your name</label><input id="name" name="name" required placeholder="Your name"></div><div class="form-group"><label for="intro">What are you curious about?</label><textarea id="intro" name="intro" required placeholder="Introduce yourself and your interests"></textarea></div><div class="form-group"><label for="motivation">Why this experience, and why now?</label><textarea id="motivation" name="motivation" required placeholder="What do you hope to learn?"></textarea></div><div class="form-group"><label for="level">Experience level</label><select id="level" name="level"><option>Complete beginner</option><option>Some experience</option><option>Practised</option></select></div><div class="form-group"><label for="needs">Dietary or health needs <span class="muted">· optional</span></label><textarea id="needs" name="needs" placeholder="Only share what your host needs to accommodate you"></textarea></div><div class="form-group"><label for="message">A message for your host <span class="muted">· optional</span></label><textarea id="message" name="message" placeholder="A question or anything else you’d like to say"></textarea></div><div class="notice">The host replies within 72 hours. You’re only charged once accepted. Payment is held securely until your experience starts. <b>This is a proposed policy: no payment or message is sent in this prototype.</b></div><br><button class="btn" type="submit">Send sample request ↗</button></form><aside class="panel"><h3>${esc(e.title)}</h3><p>${esc(e.place)}<br>${esc(selectedDate||'Date to be chosen')} · ${duration(selectedDuration||e.days[0])}</p><p class="muted">A request is an introduction, not a confirmed booking.</p></aside></div></main>`}
function journey(){let r=state.requests.at(-1);if(!r)return `<main class="narrow"><div class="page-head"><div class="eyebrow">Your journey</div><h1>Good things begin with curiosity.</h1><p class="sub">Your requests, preparations and host messages will come together here.</p></div><div class="panel"><h2>Nothing requested yet</h2><p>Explore an experience and send a sample request to see how your journey might work.</p><div class="button-row"><a class="btn" href="#/discover">Discover experiences ↗</a><button class="btn outline" data-action="sample-journey">Explore a sample accepted journey</button></div></div><div class="section-sm">${safetyPanel()}</div></main>`;let e=find(r.id);return `<main class="narrow"><div class="page-head"><div class="eyebrow">Your journey · sample request</div><h1>${r.status==='accepted'?'Your time elsewhere awaits.':r.status==='completed'?'Welcome home.':'A little hello is on its way.'}</h1><p class="sub">${esc(e.title)} · ${esc(e.place)} · ${esc(r.date)} · ${duration(r.duration)}</p><span class="status">${r.status==='pending'?'Awaiting host reply':r.status==='accepted'?'Accepted · sample journey':r.status==='completed'?'Experience completed':'Request declined'}</span></div><div class="tabs"><a href="#/journey" class="active">Your journey</a><a href="#/profile">Your profile</a><a href="#/host">Host view</a></div>${r.status==='pending'?`<div class="panel"><h2>Your request is with ${esc(e.host.split(' ')[0])}.</h2><p>The proposed response time is within 72 hours. You won’t be charged until accepted. This is a demonstration and no request was sent.</p><a class="btn outline" href="#/host">Open host view to simulate a reply ↗</a></div>`:r.status==='declined'?`<div class="panel"><h2>This sample request was declined.</h2><p>Nothing was charged. Try a different experience or date.</p><a class="btn" href="#/discover">Discover experiences</a></div>`:`<div class="two"><section class="panel"><div class="eyebrow">Your countdown</div><h2>${r.status==='completed'?'A story to carry with you':countdown(r.date)}</h2><p>${r.status==='completed'?'Your sample experience is complete.':'until your sample experience starts.'}</p><p><b>${esc(e.host)}</b><br>${esc(e.place)} · ${esc(r.date)}</p></section><section class="panel"><div class="eyebrow">Need a hand?</div><h2>Travel with care</h2><p>Review your travel insurance and keep local emergency contacts close.</p><div class="button-row"><button class="btn outline small" data-action="emergency">Emergency info</button><button class="btn outline small" data-action="report">Report a problem</button></div></section></div><section class="section-sm"><div class="row"><div><div class="eyebrow">Before you go</div><h2>Your preparation list</h2></div><span class="badge">Sample checklist</span></div><div class="checklist">${['Check visa and passport requirements','Consult a travel health professional about vaccines','Review your travel insurance','Pack for the weather and your host’s activities','Learn a few words in the local language','Read the cultural primer and seasonal notes','Save local emergency numbers and host contact'].map((x,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks?.includes(i)?'checked':''}> ${x}</label>`).join('')}</div><p class="muted">Visa, health and seasonal requirements depend on your nationality, itinerary and dates; check current official guidance.</p></section><section class="section-sm"><div class="two"><div class="panel"><h3>Your cultural primer</h3><p>Ask before taking photos. Follow ${esc(e.host.split(' ')[0])}’s lead on dress, meals and tools. Private family spaces and ceremonies are outside the experience unless your host explicitly invites you.</p><p><b>Language basics:</b> Ask your host how to say hello and thank you in ${esc(e.language)}; practise a little each day.</p></div><div class="panel"><h3>Seasonal notes</h3><p>Best season: ${esc(e.season)}. Weather, harvests and workshop activities change throughout the year. Your host would confirm a packing list and conditions before departure.</p></div></div></section><section class="section-sm"><div class="two"><div class="panel"><h3>Messages with ${esc(e.host.split(' ')[0])}</h3><p class="muted">Sample conversation · Messages stay in this browser.</p>${state.messages.filter(m=>m.id===e.id).map(m=>`<p class="note"><b>${esc(m.from)}:</b> ${esc(m.text)}</p>`).join('')||'<p class="note">Your host: Looking forward to meeting you and sharing my practice.</p>'}<form id="message-form" data-id="${e.id}"><div class="form-group"><label for="msg">Your message</label><textarea id="msg" name="message" required placeholder="Ask your host a question"></textarea></div><button class="btn small">Send sample message</button></form></div><div class="panel"><h3>Payment & documents</h3><p>Sample payment: held securely until the experience starts. No actual transaction has taken place.</p><p>Booking details, receipt and host contact would appear here once available.</p><button class="btn outline small" data-action="insurance">Travel insurance</button></div></div></section>${r.status==='accepted'?`<div class="panel"><h3>Trying the post-experience flow?</h3><p>Mark this sample experience complete to explore reviews and ways to stay connected.</p><button class="btn" data-action="complete">Mark sample complete</button></div>`:`<div class="panel"><h3>Reflect on what you learned.</h3><p>Share your experience, add a photo of what you made, or leave a review for your host.</p><a class="btn" href="#/after">Continue to reflection ↗</a></div>`}`}</main>`}
function countdown(date){let x=Math.ceil((new Date(date+'T00:00:00')-new Date())/86400000);return x>0?`${x} days`:x===0?'Today is the day':'Your journey has begun'}function safetyPanel(){return `<div class="note"><strong>Here when you need us.</strong> &nbsp; Safety information, emergency contacts, reporting and clear cancellation terms are part of the proposed journey. All support functions are simulated.</div>`}
function after(){let r=state.requests.at(-1);if(!r||r.status!=='completed')return `<main class="narrow section"><h1>After your experience</h1><p>Reviews become available after your sample experience is complete.</p><a class="btn" href="#/journey">Go to your journey</a></main>`;let e=find(r.id);return `<main class="narrow"><div class="page-head"><div class="eyebrow">Take the learning with you</div><h1>What will stay with you?</h1><p class="sub">Reflect on the experience and share your learning in your own words.</p></div><div class="form-layout"><div><form id="review-form" class="form-card"><h2>Review your experience</h2>${state.review?`<p class="note"><b>Saved review:</b> ${esc(state.review.review)}</p>`:''}<p class="sub">Your review of ${esc(e.host)} is available after completion. The host can also review the guest.</p><div class="form-group"><label>Overall experience</label><select name="rating"><option>★★★★★ · Wonderful</option><option>★★★★☆ · Very good</option><option>★★★☆☆ · Good</option><option>★★☆☆☆ · Needs improvement</option><option>★☆☆☆☆ · Disappointing</option></select></div><div class="form-group"><label for="review">What did you learn?</label><textarea id="review" name="review" required placeholder="Share a skill, memory or moment"></textarea></div><div class="form-group"><label for="made">What did you make or practise?</label><textarea id="made" name="made" placeholder="A journal entry, a finished piece, or a new skill"></textarea></div><div class="form-group"><label for="photo">Share a photo <span class="muted">· optional, demo only</span></label><input id="photo" type="file" accept="image/*"></div><button class="btn">Save sample review</button></form><div class="panel"><h3>Stay connected</h3><p>Keep in touch with ${esc(e.host)} and follow the community’s work, with their permission.</p><a class="btn outline small" href="#/journey">Return to messages</a></div></div><aside class="panel"><h3>A note from your host</h3>${state.hostReview?`<p class="note">${esc(state.hostReview)}</p>`:`<p class="muted">After completion, hosts can leave a review of their guest. A sample host review can be added from the host view.</p>`}<a href="#/host">Go to host view ↗</a><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Where next?</h3><p>Keep exploring the practices that spark your curiosity.</p><a class="btn outline small" href="#/discover">Find your next experience</a></aside></div></main>`}
function profile(){let saved=experiences.filter(e=>state.saved.includes(e.id));return `<main class="wrap"><div class="page-head"><div class="eyebrow">Your corner of elsewhere</div><h1>Your profile.</h1><p class="sub">The places you’re curious about and the journeys you’ve imagined.</p></div><div class="tabs"><a class="active" href="#/profile">Wishlist (${saved.length})</a><a href="#/journey">Requests & journeys (${state.requests.length})</a></div>${state.requests.length?`<section class="section-sm"><h2>Your requests</h2>${state.requests.map(r=>{let e=find(r.id);return `<div class="panel row" style="margin-bottom:10px"><div><b>${esc(e.title)}</b><p class="muted" style="margin:5px 0 0">${esc(r.date)} · ${duration(r.duration)}</p></div><span class="status">${esc(r.status)}</span></div>`}).join('')}</section>`:''}<section class="section-sm"><div class="section-title"><div><div class="eyebrow">Keep dreaming</div><h2>Your wishlist</h2></div><a href="#/discover">Discover more ↗</a></div><div class="grid">${saved.length?cards(saved):'<div class="empty">Save an experience with ♡ and it will be waiting here.</div>'}</div></section></main>`}
function host(){let requests=state.requests;return `<main class="wrap"><div class="page-head"><div class="eyebrow">A space for hosts · illustrative</div><h1>Welcome, ${requests.length?esc(find(requests.at(-1).id).host.split(' ')[0]):'host'}.</h1><p class="sub">Your knowledge, your terms, your community.</p></div><div class="tabs"><a class="active" href="#/host">Overview</a><a href="#/host-onboarding">Host verification</a><a href="#/journey">Guest view</a></div><div class="three"><div class="panel"><div class="eyebrow">Your host profile</div><h3>${requests.length?esc(find(requests.at(-1).id).host):'Your story goes here'}</h3><p>Set your story, teaching languages and community boundaries.</p><button class="btn outline small" data-action="host-profile">View profile</button></div><div class="panel"><div class="eyebrow">Your calendar</div><h3>Available dates</h3><p>${requests.length?'Sample date: '+esc(requests.at(-1).date):'Add dates that work for your life and practice.'}</p><button class="btn outline small" data-action="calendar">View sample calendar</button></div><div class="panel"><div class="eyebrow">Earnings & impact</div><h3>${requests.some(r=>r.status==='accepted'||r.status==='completed')?euro(Math.round((requests.at(-1).total||find(requests.at(-1).id).price)*.65)):'€0'} <small class="muted">sample host share</small></h3><p>Example split: 65% host, 10% community fund, 25% platform and support.</p></div></div><section class="section-sm"><div class="section-title"><div><div class="eyebrow">Personal introductions</div><h2>Incoming requests</h2></div><span class="badge">${requests.length} sample requests</span></div>${requests.length?requests.slice().reverse().map((r,i)=>{let e=find(r.id),index=requests.length-1-i;return `<div class="panel" style="margin-bottom:15px"><div class="row"><div><h3>${esc(r.name)} · ${esc(e.title)}</h3><p class="muted">${esc(r.date)} · ${duration(r.duration)} · ${esc(r.level)}</p></div><span class="status">${esc(r.status)}</span></div><p><b>Interests:</b> ${esc(r.intro)}<br><b>Motivation:</b> ${esc(r.motivation)}${r.needs?`<br><b>Accommodation needs:</b> ${esc(r.needs)}`:''}${r.message?`<br><b>Message:</b> ${esc(r.message)}`:''}</p>${r.status==='pending'?`<div class="button-row"><button class="btn small" data-host-decision="accept" data-index="${index}">Accept sample request</button><button class="btn outline small" data-host-decision="decline" data-index="${index}">Decline</button></div>`:r.status==='completed'?`<button class="btn outline small" data-action="host-review">Write a guest review</button>`:`<a class="btn outline small" href="#/journey">Open messages ↗</a>`}</div>`}).join(''):'<div class="panel"><p>No sample requests yet. Send one from an experience to see it here.</p><a class="btn outline small" href="#/discover">Browse experiences</a></div>'}</section><div class="section-sm">${safetyPanel()}</div></main>`}
function hostOnboarding(){return `<main class="narrow"><div class="page-head"><a class="back" href="#/host">← Back to host view</a><div class="eyebrow">Host onboarding</div><h1>Let’s build trust, together.</h1><p class="sub">Before welcoming a guest, hosts complete three verification steps. This flow is illustrative and collects no documents.</p></div><div class="form-card"><h2>01 &nbsp; Identity</h2><p>Confirm your identity through a secure verification process.</p><label class="check"><input type="checkbox" class="verify-step"> &nbsp; I understand the identity step</label></div><div class="form-card"><h2>02 &nbsp; References</h2><p>Provide references who can speak to your experience and community connection.</p><label class="check"><input type="checkbox" class="verify-step"> &nbsp; I understand the references step</label></div><div class="form-card"><h2>03 &nbsp; Site check</h2><p>A local partner reviews the proposed setting, safety information, accessibility and host-defined boundaries.</p><label class="check"><input type="checkbox" class="verify-step"> &nbsp; I understand the site check</label></div><button class="btn" data-action="verify">Complete sample onboarding</button><p class="muted" style="font-size:12px">A sample badge does not mean any real verification has occurred.</p></main>`}
function render(){let parts=location.hash.replace(/^#\/?/,'').split('/'),route=parts[0]||'home',e=find(parts[1]);let html=route==='home'?home():route==='discover'?discover():route==='experience'&&e?detail(e):route==='dates'&&e?dates(e):route==='request'&&e?request(e):route==='journey'?journey():route==='after'?after():route==='profile'?profile():route==='host'?host():route==='host-onboarding'?hostOnboarding():home();app.innerHTML=html;if(route==='experience')requestAnimationFrame(updateDetailNav);document.title=(route==='home'?'Live and learn':route==='experience'&&e?e.title:route[0].toUpperCase()+route.slice(1))+' · Elsewhere Academy';window.scrollTo(0,0)}window.addEventListener('hashchange',render);
function preserve(){let y=window.scrollY;render();window.scrollTo(0,y)}function modal(title,body,actions='<button class="btn outline small" data-close>Close</button>'){let d=document.createElement('dialog');d.innerHTML=`<div class="row"><h2 style="font-size:27px;margin:0">${title}</h2><button class="chip" data-close aria-label="Close">×</button></div><div style="margin:20px 0">${body}</div><div class="button-row">${actions}</div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal()}
const quizQuestions=[{key:'duration',q:'How much time do you have?',intro:'There is room for a meaningful experience in the time you have.',answers:[[2,'A weekend'],[7,'About a week'],[14,'Two weeks'],[30,'Up to a month']]},{key:'interest',q:'What would you love to learn?',intro:'Follow the thing you keep coming back to.',answers:[['Food','Food & fermentation'],['Craft','Craft & making'],['Music','Music & rhythm'],['Agriculture','Growing & nature'],['Wellness','Wellness'],['Language','Language'],['Building','Building']]},{key:'comfort',q:'How much comfort feels right?',intro:'Both simple stays and extra comforts can be meaningful.',answers:[[2,'Simple & close to daily life'],[3,'A balance of comfort & simplicity'],[4,'A little more comfort']]}];function quiz(){let q=quizQuestions[quizStep];modal(`0${quizStep+1} / 03`, `<h2 style="margin:0 0 12px">${q.q}</h2><p class="muted">${q.intro}</p><div class="chips">${q.answers.map(([v,l])=>`<button class="chip" data-quiz="${esc(v)}">${esc(l)}</button>`).join('')}</div>`,quizStep?'<button class="btn outline small" data-quiz-back>← Back</button>':'<button class="btn outline small" data-close>Skip quiz</button>')}
app.addEventListener('click',e=>{let t=e.target.closest('button, [data-action=gallery]');if(!t)return;if(t.dataset.save){let id=+t.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();preserve();toast(state.saved.includes(id)?'Saved to your wishlist':'Removed from wishlist');return}if(t.dataset.openPhoto){detailGallery(find(t.dataset.openPhoto),Number(t.dataset.photoIndex||0));return}if(t.dataset.scroll){document.getElementById(t.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(t.hasAttribute('data-close-booking')){document.querySelector('#booking-card')?.classList.remove('mobile-open');return}if(t.dataset.detailBook){if(t.closest('.mobile-booking-bar')){document.querySelector('#booking-card')?.classList.add('mobile-open');document.querySelector('#date-trigger')?.focus();return}to('dates/'+t.dataset.detailBook);return}if(t.dataset.askHost){let host=find(t.dataset.askHost);modal('Ask '+esc(host.host.split(' ')[0]),`<p>Write a question about the experience, accommodation or what you will learn.</p><div class="form-group"><label for="host-question">Your question</label><textarea id="host-question" placeholder="What would you like to know?"></textarea></div>`,`<button class="btn small" data-send-question="${host.id}">Save question</button>`);return}if(t.dataset.share){let url=location.origin+location.pathname+'#/experience/'+t.dataset.share;if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(()=>toast('Experience link copied')).catch(()=>modal('Share this experience',`<p>Copy this link:</p><input style="width:100%;padding:12px" readonly value="${esc(url)}">`))}else modal('Share this experience',`<p>Copy this link:</p><input style="width:100%;padding:12px" readonly value="${esc(url)}">`);return}if(t.dataset.view){view=t.dataset.view;preserve();return}if(t.dataset.removeFilter){filters[t.dataset.removeFilter]='';preserve();return}if(t.dataset.goto){to(t.dataset.goto);return}if(t.dataset.nextRequest){if(!selectedDate){toast('Choose a start date to continue.');$('#start')?.focus();return}to('request/'+t.dataset.nextRequest);return}if(t.dataset.hostDecision){let r=state.requests[+t.dataset.index];r.status=t.dataset.hostDecision==='accept'?'accepted':'declined';save();preserve();toast('Sample request '+r.status);return}let a=t.dataset.action;if(!a)return;if(a==='open-filters'){openFilters();return}if(a==='clear-filters'){filters={q:'',interest:'',continent:'',duration:'',budget:'',month:'',comfort:'',language:'',cohort:''};preserve()}if(a==='quiz'){quizStep=0;quiz()}if(a==='emergency')modal('Emergency information','<p>In a real emergency, contact local emergency services immediately. A confirmed local emergency number and host contact would be shared before departure.</p><p class="notice">This is a prototype; no emergency service is connected.</p>');if(a==='report')modal('Report a problem','<p>In a live service, you could report a safety or booking concern to the support team.</p><div class="form-group"><label for="problem">Tell us what happened</label><textarea id="problem" placeholder="Describe your concern"></textarea></div><p class="notice">This prototype cannot send reports or provide live support.</p>');if(a==='insurance')modal('Travel insurance','<p>Choose travel insurance that covers medical expenses, cancellation and the activities you plan to do. Read the provider’s terms and check destination-specific requirements.</p>');if(a==='calendar')modal('Sample host calendar','<p>Hosts can choose dates and capacity around their own work and community commitments.</p><input type="date" aria-label="Sample availability date" value="2027-04-12"><p class="muted">Illustrative calendar only. No availability is published.</p>');if(a==='host-profile')modal('Your host profile','<p>Introduce your practice, your community, teaching languages, accessibility and what you choose to share with guests.</p><p class="notice">This is a sample host view; profiles are fictional.</p>');if(a==='gallery')modal('Experience gallery',`<div class="two">${picture(find(t.dataset.id))}${picture(find(t.dataset.id))}</div><p class="muted">Illustrative images of the practice, not a confirmed host or venue.</p>`);if(a==='verify'){if(document.querySelectorAll('.verify-step:checked').length!==3){toast('Review all three steps first.');return}state.hostVerified=true;save();toast('Sample onboarding completed');to('host')}if(a==='sample-journey'){let e=find(1);state.requests.push({id:e.id,name:'Alex Morgan',intro:'I’m curious about tea and the people who grow it.',motivation:'I have two weeks to learn something with my hands.',level:'Complete beginner',date:'2027-05-10',duration:14,status:'accepted',needs:'',message:''});save();render()}if(a==='complete'){let r=state.requests.at(-1);r.status='completed';save();to('after')}if(a==='host-review')modal('Review your guest','<p>Host reviews are only available after an experience is complete.</p><div class="form-group"><label for="hostreview">Your review</label><textarea id="hostreview" placeholder="Share what it was like to host your guest"></textarea></div>','<button class="btn small" data-sample-review>Save sample host review</button>');});
app.addEventListener('change',e=>{let el=e.target;if(el.hasAttribute('data-sort')){sortOrder=el.value;preserve();return}if(el.dataset.filter){filters[el.dataset.filter]=el.value;preserve()}if(el.id==='detail-date'){selectedDate=el.value;updateDetailBooking();return}if(el.id==='detail-duration'){selectedDuration=+el.value;updateDetailBooking();return}if(el.id==='detail-guests'){guestCount=+el.value;updateDetailBooking();return}if(el.id==='guest-count'){guestCount=+el.value;preserve();return}if(el.id==='start')selectedDate=el.value;if(el.id==='duration'){selectedDuration=+el.value;preserve()}if(el.dataset.extra){extras=el.checked?[...new Set([...extras,el.dataset.extra])]:extras.filter(x=>x!==el.dataset.extra);preserve()}if(el.dataset.check!==undefined){let id=+el.dataset.check;state.checks=state.checks||[];state.checks=el.checked?[...new Set([...state.checks,id])]:state.checks.filter(x=>x!==id);save()}});
app.addEventListener('submit',e=>{e.preventDefault();let f=e.target,data=new FormData(f);if(f.id==='search-form'){filters.q=data.get('search').trim();preserve()}if(f.id==='request-form'){let id=+f.dataset.id;state.requests.push({id,name:data.get('name'),intro:data.get('intro'),motivation:data.get('motivation'),level:data.get('level'),needs:data.get('needs'),message:data.get('message'),date:selectedDate,duration:selectedDuration,guests:guestCount,extras:[...extras],total:(Math.round(find(id).price*selectedDuration/7)+extras.reduce((n,x)=>n+Number(x),0))*guestCount,status:'pending'});save();to('journey')}if(f.id==='message-form'){state.messages.push({id:+f.dataset.id,from:'You',text:data.get('message')});save();preserve();toast('Sample message saved in this browser')}if(f.id==='review-form'){state.review={rating:data.get('rating'),review:data.get('review'),made:data.get('made')};save();toast('Sample review saved in this browser');to('journey')}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||!b.closest('dialog'))return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.sendQuestion){let input=document.querySelector('#host-question'),msg=input.value.trim();if(!msg){toast('Write a question first');return}state.messages.push({id:Number(b.dataset.sendQuestion),from:'You',text:msg});save();b.closest('dialog').close();toast('Question saved');}if(b.hasAttribute('data-sample-review')){let v=document.querySelector('#hostreview').value.trim();if(!v){toast('Write a short review first');return}state.hostReview=v;save();b.closest('dialog').close();toast('Sample host review saved')}if(b.dataset.quiz!==undefined){let q=quizQuestions[quizStep];state.quiz[q.key]=b.dataset.quiz;b.closest('dialog').close();if(quizStep<2){quizStep++;quiz()}else{filters={q:'',continent:'',budget:'',month:'',language:'',cohort:'',duration:state.quiz.duration,interest:state.quiz.interest,comfort:state.quiz.comfort};save();to('discover');if(location.hash==='#/discover')render()}}if(b.hasAttribute('data-quiz-back')){b.closest('dialog').close();quizStep--;quiz()}});
render();

app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action=gallery]')){e.preventDefault();e.target.click()}});

function updateDetailBooking(){let e=find(activeBookingId),per=Math.round(e.price*selectedDuration/7),total=bookingTotal(e),set=(id,value)=>{let el=document.getElementById(id);if(el)el.textContent=value};let breakdown=document.querySelector('.booking-breakdown');if(breakdown)breakdown.hidden=!selectedDate;set('detail-price',euro(per));set('detail-rate',`${euro(per)} × ${guestCount} ${guestCount===1?'guest':'guests'}`);set('detail-subtotal',euro(total));set('detail-total',euro(total));set('mobile-price','From '+euro(per));let mobile=document.querySelector('#mobile-price');if(mobile)mobile.nextElementSibling.textContent=`per person · ${duration(selectedDuration)}`;set('date-trigger',selectedDate?new Date(selectedDate+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})+' – '+endDate(selectedDate,selectedDuration):'Add date')}
let calendarMonth=null;
function drawCalendar(){let pane=document.querySelector('#calendar-popover');if(!pane)return;let today=new Date();today.setHours(0,0,0,0);if(!calendarMonth){let d=selectedDate?new Date(selectedDate+'T12:00:00'):today;calendarMonth=new Date(d.getFullYear(),d.getMonth(),1)}let yr=calendarMonth.getFullYear(),mo=calendarMonth.getMonth(),first=(new Date(yr,mo,1).getDay()+6)%7,days=new Date(yr,mo+1,0).getDate(),iso=d=>`${yr}-${String(mo+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;pane.innerHTML=`<div class="calendar-head"><button type="button" data-cal-nav="-1" aria-label="Previous month">‹</button><strong>${calendarMonth.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</strong><button type="button" data-cal-nav="1" aria-label="Next month">›</button></div><div class="calendar-grid">${['M','T','W','T','F','S','S'].map(x=>`<span aria-hidden="true">${x}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{let d=i+1,date=new Date(yr,mo,d),v=iso(d);return `<button type="button" data-cal-date="${v}" aria-label="${date.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}" ${date<today?'disabled':''} class="${v===selectedDate?'selected':''}">${d}</button>`}).join('')}</div>`}
app.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;let pane=document.querySelector('#calendar-popover'),trigger=document.querySelector('#date-trigger');if(b.id==='date-trigger'){pane.hidden=!pane.hidden;trigger.setAttribute('aria-expanded',String(!pane.hidden));if(!pane.hidden)drawCalendar()}else if(b.dataset.calNav){calendarMonth.setMonth(calendarMonth.getMonth()+Number(b.dataset.calNav));drawCalendar()}else if(b.dataset.calDate){selectedDate=b.dataset.calDate;pane.hidden=true;trigger.setAttribute('aria-expanded','false');updateDetailBooking();trigger.focus()}});
document.addEventListener('click',ev=>{let pane=document.querySelector('#calendar-popover'),trigger=document.querySelector('#date-trigger');if(pane&&!pane.hidden&&!pane.contains(ev.target)&&ev.target!==trigger){pane.hidden=true;trigger.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){let pane=document.querySelector('#calendar-popover');if(pane&&!pane.hidden){pane.hidden=true;let trigger=document.querySelector('#date-trigger');trigger.setAttribute('aria-expanded','false');trigger.focus()}}});
function updateDetailNav(){let sections=['overview','host','day','stay','reviews'],current=sections[0];sections.forEach(id=>{let el=document.getElementById(id);if(el&&el.getBoundingClientRect().top<=140)current=id});document.querySelectorAll('.detail-nav button').forEach(b=>{let active=b.dataset.scroll===current;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')})}window.addEventListener('scroll',updateDetailNav,{passive:true});
app.addEventListener('scroll',e=>{if(e.target.id==='gallery-mobile'){let n=Math.round(e.target.scrollLeft/e.target.clientWidth)+1,c=document.querySelector('#gallery-counter');if(c)c.textContent=`${Math.min(5,n)} / 5`}},true);
